#pragma once
// ============================================================================
// src/render/vulkan/tweak_overlay_vulkan.h -- the debug tweak overlay's Vulkan renderer (NOT RETAIL)
// ============================================================================
// Debug flavour only (BANISHED_TWEAK_OVERLAY; src/diag/tweak_overlay.h). Our own Dear ImGui renderer on
// this backend's resources (resources.h) and its 1.1 / 1.3 rendering helpers (vulkan11.h): one pipeline
// (shaders in tweak_overlay/, generated by tools/vulkan/gen_tweak_overlay_spirv.sh), one host-visible
// vertex and index buffer per frame-in-flight slot, one descriptor set per ImGui texture (the font
// atlas), ImGui 1.92's texture requests honoured with whole-image uploads.
// ============================================================================
#if BANISHED_TWEAK_OVERLAY

#include "vk_api.h"

namespace VideoVulkan {

// True while the overlay is open (one atomic load): DrawEndFrame records the overlay pass only then.
bool TweakOverlayOpen();

// DrawEndFrame, the frame's last image in COLOR_ATTACHMENT_OPTIMAL (left there): the overlay drawn over
// it. `slot` is the frame-in-flight slot (its fence waited for); `format` the image's format.
void TweakOverlayRecord(VkCommandBuffer cb, unsigned slot, VkImageView view, VkExtent2D extent, VkFormat format);

// The device shutdown, the device idle, before ResourcesShutdown: every object the renderer holds.
void TweakOverlayShutdown();

}  // namespace VideoVulkan

#endif  // BANISHED_TWEAK_OVERLAY
